namespace Cnblogs.DashScope.Core;

/// <summary>
/// A conversation item of an audio chat session. A message item (Type message) carries Role and
/// Content; a function call item (Type function_call) carries CallId, Name and Arguments; a
/// function call output item (Type function_call_output) carries CallId and Output.
/// </summary>
public class AudioChatItem
{
    /// <summary>
    /// The id of the item, generated by the server when unset. conversation.item.create only,
    /// an existing id is rejected.
    /// </summary>
    public string? Id { get; set; }

    /// <summary>
    /// Always realtime.item. Server echo.
    /// </summary>
    public string? Object { get; set; }

    /// <summary>
    /// The type of the item: message, function_call or function_call_output.
    /// </summary>
    public string? Type { get; set; }

    /// <summary>
    /// The status of the item, e.g. in_progress, completed. Server echo.
    /// </summary>
    public string? Status { get; set; }

    /// <summary>
    /// The role of the message: system, user or assistant. message items only.
    /// </summary>
    public string? Role { get; set; }

    /// <summary>
    /// The content of the message. message items only; system / user / assistant support
    /// input_text / (input_text, input_audio) / output_text respectively.
    /// </summary>
    public List<AudioChatItemContent>? Content { get; set; }

    /// <summary>
    /// The id of the function call, correlating the request and the output. function_call and
    /// function_call_output items.
    /// </summary>
    public string? CallId { get; set; }

    /// <summary>
    /// The name of the function to call. function_call items.
    /// </summary>
    public string? Name { get; set; }

    /// <summary>
    /// The arguments of the function call as a JSON string. function_call items.
    /// </summary>
    public string? Arguments { get; set; }

    /// <summary>
    /// The output of the function call as a JSON string. function_call_output items.
    /// </summary>
    public string? Output { get; set; }
}
